CREATE OR REPLACE FUNCTION public.auto_create_employee_for_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_employee_number TEXT; v_random_suffix TEXT; v_existing_active_employee BOOLEAN; BEGIN IF NEW.company_id IS NOT NULL THEN SELECT EXISTS( SELECT 1 FROM employees WHERE user_id = NEW.user_id AND company_id = NEW.company_id AND is_active = true ) INTO v_existing_active_employee; IF NOT v_existing_active_employee THEN v_random_suffix := UPPER(SUBSTRING(MD5(RANDOM()::TEXT || CLOCK_TIMESTAMP()::TEXT) FROM 1 FOR 8)); v_employee_number := 'EMP-' || TO_CHAR(NOW(), 'YYYY') || '-' || v_random_suffix; INSERT INTO employees ( company_id, user_id, employee_number, first_name, last_name, first_name_ar, last_name_ar, email, hire_date, basic_salary, position, position_ar, department, department_ar, has_system_access, account_status, is_active, created_by ) VALUES ( NEW.company_id, NEW.user_id, v_employee_number, COALESCE(NEW.first_name, 'N/A'), COALESCE(NEW.last_name, 'N/A'), NEW.first_name_ar, NEW.last_name_ar, NEW.email, CURRENT_DATE, 0, 'مدير الشركة', 'Company Manager', 'الإدارة', 'Administration', true, 'active', true, auth.uid() ); END IF; END IF; RETURN NEW; END; $function$;;
